function routeTenant(tenantId, enableCanary) {
  const canaryTenants = new Set(['tenantA', 'tenantB']);
  const useCanary = enableCanary && canaryTenants.has(tenantId);
  return useCanary ? 'model-v2' : 'model-v1';
}
